      "title": "Extract formatting logic to a dedicated Formatter class",
      "rationale_metric_link": [
        "LCOM4",
        "DCC"
      ],
      "expected_effect": [
        {
          "metric": "LCOM4",
          "direction": "down",
          "confidence": 0.9
        },
        {
          "metric": "DCC",
          "direction": "up",
